draw:
var padL = 36, padR = 16, padT = 26, padB = 34;
var yMid = (H - padB + padT) / 2;
var A = (H - padT - padB) * 0.32;
var Lx = W - padL - padR;
var lam = Lx / 2.2;            // two-ish wavelengths across the picture
var k = 2 * Math.PI / lam;

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(padL, yMid); ctx.lineTo(W - padR, yMid); ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 300; i++) {
  var x = padL + Lx * i / 300;
  var y = yMid - A * Math.sin(k * (x - padL));
  if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
}
ctx.stroke();

var crest1 = padL + lam * 0.25;
var crest2 = padL + lam * 1.25;
var trough = padL + lam * 0.75;

// wavelength bar between the two crests
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
var bar = padT - 8;
ctx.beginPath(); ctx.moveTo(crest1, bar); ctx.lineTo(crest2, bar); ctx.stroke();
ctx.beginPath(); ctx.moveTo(crest1, bar); ctx.lineTo(crest1 + 6, bar - 4); ctx.lineTo(crest1 + 6, bar + 4); ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();
ctx.beginPath(); ctx.moveTo(crest2, bar); ctx.lineTo(crest2 - 6, bar - 4); ctx.lineTo(crest2 - 6, bar + 4); ctx.closePath();
ctx.fill();
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(crest1, bar); ctx.lineTo(crest1, yMid - A); ctx.stroke();
ctx.beginPath(); ctx.moveTo(crest2, bar); ctx.lineTo(crest2, yMid - A); ctx.stroke();
ctx.setLineDash([]);

// amplitude bar at the trough
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(trough, yMid); ctx.lineTo(trough, yMid + A); ctx.stroke();
ctx.beginPath(); ctx.moveTo(trough, yMid + A); ctx.lineTo(trough - 4, yMid + A - 6); ctx.lineTo(trough + 4, yMid + A - 6); ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.ink;
ctx.fillText("one wavelength, lambda", (crest1 + crest2) / 2 - 52, bar - 8);
ctx.fillText("amplitude A", trough + 8, yMid + A * 0.6);
ctx.fillText("crest", crest1 - 14, yMid - A - 8);
ctx.fillText("trough", trough + 8, yMid + A + 14);
ctx.fillText("y = 0 line (rope at rest)", padL + 4, yMid - 6);
ctx.fillText("distance x along the rope", W / 2 - 68, H - 8);
ctx.fillText("y", 10, yMid - A - 6);

ctx.strokeStyle = C.ink;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, yMid - A - 16); ctx.lineTo(padL + 30, yMid - A - 16); ctx.stroke();
ctx.beginPath(); ctx.moveTo(padL + 30, yMid - A - 16); ctx.lineTo(padL + 24, yMid - A - 20); ctx.lineTo(padL + 24, yMid - A - 12);
ctx.closePath(); ctx.fillStyle = C.ink; ctx.fill();
ctx.fillText("v", padL + 34, yMid - A - 12);
